#!/usr/bin/env python3
"""Chapter 35, lab 2 (no model): assemble the release bundle for Bulwark from the real results of Chapters 2 to 34, verify it, sign it, then do to it what a careless release does.
Evidence items are files in results/ (digest taken now).  Kinds: UNIT (pytest log), LAB_SIM (no-model labs on the SIMULATED tenant), LAB_LIVE (labs that called Haiku 4.5).
Writes results/ch35_collect.json and prints the log.  The signing key is generated for the lab and discarded."""
import sys, json, time, re, os, copy
from pathlib import Path
here = Path(__file__).resolve().parent; sys.path.insert(0, str(here))
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from bulwark.bundle import Item, Control, Bundle, make_item, module_digests, verify, sign, check_signature, bundle_digest, diff, record_signed, canonical
from bulwark.evidence import Vault, ChainLog

