 ("E01", "ch35_pytest.log", "UNIT", ("moneypath", "egress", "identity", "evidence", "tenancy", "detect", "incident", "disclosure", "supplychain", "mcpguard", "approval", "runtime_scope", "promptrelease", "budget", "registry", "docagent"), "pytest, whole suite", "unit tests of the author's own modules; they pass when the mutants of Chapter 28 that survive are not exercised"),
 ("E02", "ch08_classes.json", "LAB_SIM", ("moneypath",), SIM, "payment classes built by the author; one tenant"),
